const strip = (x) => x.trim().replace(/^[^\p{L}\d]+/u, '');
const T = {}; ORDER.forEach((l, i) => { T[l] = new Map(R.map((r) => [strip(r[0]), strip(r[i + 1])])); });
const PAT = { // [steps, step, min, progress-fn]
  es: ['pasos', 'paso', 'min', (a, b) => `Tu progreso: ${a} de ${b} lecciones`], fr: ['étapes', 'étape', 'min', (a, b) => `Votre progression : ${a} sur ${b} leçons`],
  de: ['Schritte', 'Schritt', 'Min.', (a, b) => `Dein Fortschritt: ${a} von ${b} Lektionen`], pt: ['passos', 'passo', 'min', (a, b) => `O seu progresso: ${a} de ${b} lições`], it: ['passi', 'passo', 'min', (a, b) => `I tuoi progressi: ${a} di ${b} lezioni`] };
export const languages = LANGS;
export function getLang() { try { const l = localStorage.getItem('rk_lang'); if (l && LANGS[l]) return l; } catch {} const n = (navigator.language || 'en').slice(0, 2); return T[n] ? n : 'en'; }
export function setLang(l) { try { localStorage.setItem('rk_lang', l); } catch {} location.reload(); }
const SKIP = new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'SVG', 'CODE']);
const ATTRS = ['placeholder', 'aria-label', 'title'];
const lead = /^([^\p{L}\d]*)([\s\S]*?)(\s*)$/u;
export function startI18n(root) {
  const lang = getLang(); document.documentElement.lang = lang; if (lang === 'en') return; const map = T[lang];
  const P = PAT[lang]; const SIDE = { es: ['Blancas', 'Negras'], fr: ['Blancs', 'Noirs'], de: ['Weiß', 'Schwarz'], pt: ['Brancas', 'Pretas'], it: ['Bianco', 'Nero'] }[lang];
  const PZ = { es: (c, n) => `Juegan ${c}: encuentra el mate en ${n}.`, fr: (c, n) => `Aux ${c} de jouer : trouvez le mat en ${n}.`, de: (c, n) => `${c} am Zug – finde das Matt in ${n}.`, pt: (c, n) => `Jogam as ${c}: encontre o mate em ${n}.`, it: (c, n) => `Muove il ${c}: trova il matto in ${n}.` }[lang];
  const tr = (s) => { const m = lead.exec(s); if (!m || !m[2]) return null; let t = map.get(m[2]);
    if (t == null) { let q = /^(\d+) (steps?) · (\d+) min$/.exec(m[2]); if (q) t = `${q[1]} ${q[1] === '1' ? P[1] : P[0]} · ${q[3]} ${P[2]}`; else if ((q = /^(White|Black) to move — find the checkmate in (\d+)\.$/.exec(m[2]))) t = PZ(SIDE[q[1] === 'White' ? 0 : 1], q[2]); else if ((q = /^Your progress: (\d+) of (\d+) lessons$/.exec(m[2]))) t = P[3](q[1], q[2]); } return t == null ? null : m[1] + t + m[3]; };
  const pass = (node) => {
    const w = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
    while (w.nextNode()) { const t = w.currentNode; if (SKIP.has(t.parentNode?.nodeName?.toUpperCase())) continue; const r = tr(t.nodeValue); if (r != null) t.nodeValue = r; }
    for (const e of node.querySelectorAll ? node.querySelectorAll('[placeholder],[aria-label],[title]') : []) for (const a of ATTRS) { const v = e.getAttribute(a); if (v) { const r = tr(v); if (r != null) e.setAttribute(a, r); } }
  };
  let queued = false; const run = () => { queued = false; obs.disconnect(); try { pass(root); } finally { obs.observe(root, { childList: true, subtree: true, characterData: true }); } };
  const obs = new MutationObserver(() => { if (!queued) { queued = true; requestAnimationFrame(run); } });
  run();
}
